//! The Falco catalogs, compiled in and parsed once per process.
//!
//! `data/catalogs/falco/` is generated by `scripts/engine/sync_falco_catalog.py` from the
//! Falco field reference, the plugin READMEs, and the Falco default rules.
//! An unknown field of a catalogued source is an error, as Falco refuses it; an
//! unknown macro, list, or tuned rule is a warning (Sysdig manages its own).

use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::sync::OnceLock;

const FIELDS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/data/catalogs/falco/fields.toml"
));
const DEFAULTS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/data/catalogs/falco/defaults.toml"
));
const EVENTS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/data/catalogs/falco/events.toml"
));

/// The event source of a rule when its block does not name one.
pub const DEFAULT_SOURCE: &str = "syscall";

/// One event source (`syscall`, `k8s_audit`, ...).
#[derive(Debug, Clone, Deserialize)]
pub struct Source {
    pub name: String,
    pub plugin: String,
    pub description: String,
}

/// What a field holds, for operator and value checks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Kind {
    String,
    Number,
    Bool,
    Ip,
    Other,
}

/// Whether a field takes an argument (`EPF_ARG_REQUIRED`, `EPF_ARG_ALLOWED`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ArgRule {
    None,
    Allowed,
    Required,
}

/// One Falco field, with libsinsp's type name (`CHARBUF`, `UINT64`, `IPNET`)
/// and flags.
#[derive(Debug, Clone, Deserialize)]
#[expect(
    clippy::struct_excessive_bools,
    reason = "the catalog's columns: one flag per libsinsp EPF_* field flag"
)]
pub struct Field {
    pub name: String,
    #[serde(rename = "type")]
    pub field_type: String,
    /// `EPF_IS_LIST`: the field extracts several values.
    pub list: bool,
    pub kind: Kind,
    /// libsinsp filter check class (`gen_event`, `thread`, ...) or plugin name.
    pub class: String,
    /// `libsinsp` or `plugin`.
    pub origin: String,
    /// Event sources the field applies to; `*` is every source.
    pub sources: Vec<String>,
    pub arg: ArgRule,
    /// `EPF_ARG_INDEX`: the argument may be a number.
    pub arg_index: bool,
    /// `EPF_ARG_KEY`: the argument may be a string.
    pub arg_key: bool,
    /// `EPF_NO_RHS`: no right-hand side field, and never one itself.
    pub no_rhs: bool,
    /// `EPF_NO_TRANSFORMER`.
    pub no_transformer: bool,
    /// `EPF_FILTER_ONLY`: not in output.
    pub filter_only: bool,
    /// `EPF_PRINT_ONLY`.
    pub print_only: bool,
    /// libsinsp's `EPF_DEPRECATED`, or deprecated by Falco's rule loader.
    pub deprecated: bool,
    /// The values libsinsp extracts, for an enumerated field (`fd.type`).
    #[serde(default)]
    pub values: Vec<String>,
    pub description: String,
}

impl Field {
    pub fn applies_to(&self, source: &str) -> bool {
        self.sources.iter().any(|s| s == "*" || s == source)
    }

    /// Takes an argument: `proc.aname[2]`, `evt.arg.flags`.
    pub fn takes_arg(&self) -> bool {
        self.arg != ArgRule::None
    }
}

/// A macro of the Falco default rules.
#[derive(Debug, Clone, Deserialize)]
pub struct Macro {
    pub name: String,
    pub condition: String,
    pub source: String,
    /// The first default rules file that defines it: stable, then incubating,
    /// then sandbox.
    pub origin: String,
    /// Differing definitions in later files (`<file>: <condition>`).
    #[serde(default)]
    pub also: Vec<String>,
}

/// A list of the Falco default rules.
#[derive(Debug, Clone, Deserialize)]
pub struct List {
    pub name: String,
    pub items: Vec<String>,
    /// The first default rules file that defines it (see [`Macro::origin`]).
    pub origin: String,
    /// Differing definitions in later files (`<file>: [<items>]`).
    #[serde(default)]
    pub also: Vec<String>,
}

/// A rule of the Falco default rules: what a tuning (`append_to_rule`) extends.
#[derive(Debug, Clone, Deserialize)]
pub struct Rule {
    pub name: String,
    pub condition: String,
    pub source: String,
    pub origin: String,
}

/// One event of the driver's event table: its category and its codes
/// (the enter and exit events, `PPME_*`).
#[derive(Debug, Clone, Deserialize)]
pub struct Event {
    pub name: String,
    pub kind: String,
    pub codes: Vec<String>,
}

/// An event argument (`evt.arg.<name>`, `evt.rawarg.<name>`) and its type, as
/// libsinsp's longest-match lookup first finds it.
#[derive(Debug, Clone, Deserialize)]
pub struct Param {
    pub name: String,
    #[serde(rename = "type")]
    pub param_type: String,
}

#[derive(Deserialize)]
struct FieldsFile {
    sources: Vec<Source>,
    classes: Vec<String>,
    fields: Vec<Field>,
}

#[derive(Deserialize)]
struct DefaultsFile {
    #[serde(default)]
    macros: Vec<Macro>,
    #[serde(default)]
    lists: Vec<List>,
    #[serde(default)]
    rules: Vec<Rule>,
}

#[derive(Deserialize)]
struct EventsFile {
    syscalls: Vec<String>,
    events: Vec<Event>,
    params: Vec<Param>,
}

/// Every Falco catalog.
pub struct Catalog {
    pub sources: Vec<Source>,
    pub fields: Vec<Field>,
    by_name: HashMap<String, usize>,
    pub macros: BTreeMap<String, Macro>,
    pub lists: BTreeMap<String, List>,
    /// The default lists' names in Falco's load order (`falco_rules.yaml`,
    /// then incubating, then sandbox, then the plugin rules), which decides what
    /// a list item can name and the order lists expand in.
    pub list_order: Vec<String>,
    /// The Falco default rules, by name.
    pub rules: BTreeMap<String, Rule>,
    events: BTreeMap<String, Event>,
    /// libsinsp's filter check classes, in the order it tries them.
    pub classes: Vec<String>,
    /// Event arguments, in table order.
    pub params: Vec<Param>,
    /// Syscall names (`ppm_sc` codes), which `evt.type` also accepts.
    pub syscalls: BTreeSet<String>,
    /// Every event code of the table.
    pub all_codes: BTreeSet<String>,
}

/// A field name, resolved for one event source.
#[derive(Debug, Clone, Copy)]
pub enum Lookup<'c> {
    /// The field, or the field whose argument the name carries
    /// (`evt.arg` for `evt.arg.flags`).
    Known(&'c Field),
    /// A field of another source.
    OtherSource(&'c Field),
    Unknown,
}

impl Catalog {
    #[expect(
        clippy::expect_used,
        reason = "parses a catalog compiled in with include_str!: a bad catalog fails the tests, never a user's document"
    )]
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let fields: FieldsFile =
                toml::from_str(FIELDS_TOML).expect("data/catalogs/falco/fields.toml");
            let defaults: DefaultsFile =
                toml::from_str(DEFAULTS_TOML).expect("data/catalogs/falco/defaults.toml");
            let events: EventsFile =
                toml::from_str(EVENTS_TOML).expect("data/catalogs/falco/events.toml");
            let by_name = fields
                .fields
                .iter()
                .enumerate()
                .map(|(i, f)| (f.name.clone(), i))
                .collect();
            let all_codes = events
                .events
                .iter()
                .flat_map(|e| e.codes.iter().cloned())
                .collect();
            Catalog {
                sources: fields.sources,
                classes: fields.classes,
                params: events.params,
                syscalls: events.syscalls.into_iter().collect(),
                all_codes,
                fields: fields.fields,
                by_name,
                macros: defaults
                    .macros
                    .into_iter()
                    .map(|m| (m.name.clone(), m))
                    .collect(),
                list_order: defaults.lists.iter().map(|l| l.name.clone()).collect(),
                lists: defaults
                    .lists
                    .into_iter()
                    .map(|l| (l.name.clone(), l))
                    .collect(),
                rules: defaults
                    .rules
                    .into_iter()
                    .map(|r| (r.name.clone(), r))
                    .collect(),
                events: events
                    .events
                    .into_iter()
                    .map(|e| (e.name.clone(), e))
                    .collect(),
            }
        })
    }

    pub fn source(&self, name: &str) -> Option<&Source> {
        self.sources.iter().find(|s| s.name == name)
    }

    pub fn field(&self, name: &str) -> Option<&Field> {
        self.by_name.get(name).map(|&i| &self.fields[i])
    }

    /// Resolve `name` for `source`. A dotted name whose prefix is a field that
    /// takes an argument (`evt.arg.flags`, `evt.type.is.open`) is that field.
    pub fn lookup(&self, name: &str, source: &str) -> Lookup<'_> {
        let mut candidate = name;
        let mut exact = true;
        loop {
            if let Some(field) = self.field(candidate)
                && (exact || field.takes_arg())
            {
                return if field.applies_to(source) {
                    Lookup::Known(field)
                } else {
                    Lookup::OtherSource(field)
                };
            }
            match candidate.rsplit_once('.') {
                Some((head, _)) if head.contains('.') => {
                    candidate = head;
                    exact = false;
                }
                _ => return Lookup::Unknown,
            }
        }
    }

    /// Fields that apply to `source`, in name order.
    pub fn fields_for<'c>(&'c self, source: &'c str) -> impl Iterator<Item = &'c Field> + 'c {
        self.fields.iter().filter(move |f| f.applies_to(source))
    }

    /// The category of an event of the table (`file`, `process`, `net`, ...).
    pub fn event(&self, name: &str) -> Option<&str> {
        self.events.get(name).map(|e| e.kind.as_str())
    }

    /// The event codes an event name selects.
    pub fn event_codes(&self, name: &str) -> Option<&[String]> {
        self.events.get(name).map(|e| e.codes.as_slice())
    }

    pub fn events(&self) -> impl Iterator<Item = &str> {
        self.events.keys().map(String::as_str)
    }

    /// Names a source knows, for near-miss suggestions.
    pub fn field_names_for(&self, source: &str) -> BTreeSet<&str> {
        self.fields
            .iter()
            .filter(|f| f.applies_to(source))
            .map(|f| f.name.as_str())
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogs_load_with_every_source() {
        let c = Catalog::cached();
        for source in [
            "syscall",
            "k8s_audit",
            "aws_cloudtrail",
            "okta",
            "github",
            "gcp_auditlog",
        ] {
            assert!(c.source(source).is_some(), "{source}");
            assert!(c.fields_for(source).count() > 5, "{source}");
        }
        assert!(c.macros.contains_key("spawned_process"));
        assert!(c.lists.contains_key("shell_binaries"));
        assert_eq!(c.event("execve"), Some("process"));
        assert!(c.syscalls.contains("execveat"));
        assert!(c.params.iter().any(|p| p.name == "flags"));
        assert_eq!(c.classes.first().map(String::as_str), Some("gen_event"));
    }

    #[test]
    fn lookup_resolves_arguments_and_sources() {
        let c = Catalog::cached();
        assert!(matches!(c.lookup("proc.name", "syscall"), Lookup::Known(_)));
        assert!(
            matches!(c.lookup("evt.arg.flags", "syscall"), Lookup::Known(f) if f.name == "evt.arg")
        );
        assert!(matches!(
            c.lookup("evt.time", "k8s_audit"),
            Lookup::Known(_)
        ));
        assert!(matches!(
            c.lookup("ka.verb", "syscall"),
            Lookup::OtherSource(_)
        ));
        assert!(matches!(c.lookup("proc.nmae", "syscall"), Lookup::Unknown));
        assert!(matches!(
            c.lookup("proc.name.extra", "syscall"),
            Lookup::Unknown
        ));
    }
}
